import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-about',
    standalone: true,
    imports: [CommonModule],
    template: `
    <section id="about" class="about-section">
      <div class="container">
        <h2 class="section-title">About Me</h2>
        <div class="about-content">
          <div class="text-card fade-in">
            <p>
              I am a passionate <strong>Full-Stack Web Developer</strong> based in Morocco, with a BTS in Web Development. 
              I specialize in building robust and scalable applications using <strong>Angular</strong> and <strong>Spring Boot</strong>.
            </p>
            <p>
              My philosophy focuses on writing clean, performant, and secure code. I enjoy translating complex requirements into simple, 
              elegant, and user-friendly interfaces. Whether it's a sleek frontend or a powerful backend API, I love the challenge of creating 
              seamless web experiences.
            </p>
          </div>
        </div>
      </div>
    </section>
  `,
    styles: [`
    .about-section {
      background-color: var(--card-bg);
    }
    .section-title {
      text-align: center;
      margin-bottom: 3rem;
      font-size: 2.5rem;
      color: var(--primary-color);
    }
    .about-content {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }
    .text-card p {
      margin-bottom: 1.5rem;
      font-size: 1.1rem;
      line-height: 1.8;
      color: var(--text-color);
    }
  `]
})
export class AboutComponent { }
